import sys, json, os
sys.path.append('storage/shared')
from meta.sas.scheduler_client_v0_5_adapter import recommend, gate, next_offsets

scenarios = {
  "sequential": {"offsets": [0,2,4,6,8], "hazard_resolved": True},
  "parallel":   {"offsets": [0,2,4,6,8], "hazard_resolved": True},
  "scatter":    {"offsets": [None],      "hazard_resolved": True},
}

out = {}
for mode, cfg in scenarios.items():
  decisions = []
  for off in cfg["offsets"]:
    rec = recommend(mode, off, cfg["hazard_resolved"])
    if off is None:
      gd = {"allow": False, "reason": "N/A for scatter"}
    else:
      gd = gate(mode, cfg["hazard_resolved"], off)
    decisions.append({"offset": off, "recommend": rec, "gate": gd})
  out[mode] = {
    "decisions": decisions,
    "next_offsets": next_offsets(mode, observed=[o for o in cfg["offsets"] if o is not None])
  }

os.makedirs('storage/shared/meta/sas/derived', exist_ok=True)
path = 'storage/shared/meta/sas/derived/scheduler_v0_5_demo.json'
with open(path, 'w', encoding='utf-8') as f:
  json.dump(out, f, indent=2)
print(json.dumps({"written": path, "modes": list(out.keys())}, indent=2))
